from pathlib import Path

path = Path('app/src/main/java/com/clickgo/passageiro/MainActivity.java')
text = path.read_text(encoding='utf-8')

# No seletor de destino, a foto sempre começa na origem real do passageiro.
old_initial = '''        GeoPoint initial = forOrigin ? origin : (destination != null ? destination : origin);\n'''
new_initial = '''        GeoPoint initial = forOrigin ? origin : origin;\n'''
if old_initial not in text:
    raise SystemExit('Inicialização do seletor não encontrada')
text = text.replace(old_initial, new_initial, 1)

old_block = '''        final GeoPoint[] chosen = { initial };\n        Marker selected = new Marker(picker);\n        selected.setPosition(initial);\n        selected.setTitle(forOrigin ? "Embarque escolhido" : "Destino escolhido");\n        selected.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        selected.setDraggable(true);\n        selected.setOnMarkerDragListener(new Marker.OnMarkerDragListener() {\n            @Override public void onMarkerDrag(Marker marker) {\n                chosen[0] = marker.getPosition();\n            }\n            @Override public void onMarkerDragEnd(Marker marker) {\n                chosen[0] = marker.getPosition();\n                picker.getController().animateTo(marker.getPosition());\n                picker.invalidate();\n            }\n            @Override public void onMarkerDragStart(Marker marker) {\n                chosen[0] = marker.getPosition();\n            }\n        });\n        picker.getOverlays().add(selected);\n\n        MapEventsOverlay events = new MapEventsOverlay(new MapEventsReceiver() {\n            @Override public boolean singleTapConfirmedHelper(GeoPoint point) {\n                chosen[0] = point;\n                selected.setPosition(point);\n                selected.setTitle(forOrigin ? "Embarque escolhido" : "Destino escolhido");\n                picker.getController().animateTo(point);\n                picker.invalidate();\n                return true;\n            }\n            @Override public boolean longPressHelper(GeoPoint point) {\n                return singleTapConfirmedHelper(point);\n            }\n        });\n        picker.getOverlays().add(0, events);\n        TextView tip = text(forOrigin ? "Toque no mapa ou arraste o marcador para ajustar o embarque." : "Toque no mapa ou arraste o marcador para escolher o DESTINO.", 13, Color.WHITE, true);\n'''

new_block = '''        final GeoPoint[] chosen = { initial };\n        final GeoPoint fixedOrigin = origin == null ? null : new GeoPoint(origin.getLatitude(), origin.getLongitude());\n\n        // Mantém a origem visível enquanto a foto é arrastada. É apenas um ponto leve, sem rede.\n        final Polyline previewLine = new Polyline();\n        if (!forOrigin && fixedOrigin != null) {\n            Marker pickup = new Marker(picker);\n            pickup.setPosition(fixedOrigin);\n            pickup.setTitle("Embarque");\n            GradientDrawable pickupDot = new GradientDrawable();\n            pickupDot.setShape(GradientDrawable.OVAL);\n            pickupDot.setColor(GREEN);\n            pickupDot.setStroke(dp(3), Color.WHITE);\n            pickupDot.setSize(dp(22), dp(22));\n            pickup.setIcon(pickupDot);\n            pickup.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_CENTER);\n            picker.getOverlays().add(pickup);\n\n            previewLine.setPoints(Arrays.asList(fixedOrigin, initial));\n            previewLine.getOutlinePaint().setStrokeWidth(dp(4));\n            previewLine.getOutlinePaint().setColor(Color.rgb(48, 92, 220));\n            picker.getOverlays().add(previewLine);\n        }\n\n        Marker selected = new Marker(picker);\n        selected.setPosition(initial);\n        selected.setTitle(forOrigin ? "Embarque escolhido" : "Arraste sua foto até o destino");\n        if (!forOrigin) selected.setIcon(PassengerAvatar.markerDrawable(this));\n        selected.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        selected.setDraggable(true);\n        selected.setOnMarkerDragListener(new Marker.OnMarkerDragListener() {\n            @Override public void onMarkerDrag(Marker marker) {\n                // Durante o gesto só guardamos a coordenada: nada de HTTP, rota ou animação.\n                chosen[0] = marker.getPosition();\n            }\n            @Override public void onMarkerDragEnd(Marker marker) {\n                chosen[0] = marker.getPosition();\n                if (!forOrigin && fixedOrigin != null) {\n                    previewLine.setPoints(Arrays.asList(fixedOrigin, marker.getPosition()));\n                }\n                picker.invalidate();\n            }\n            @Override public void onMarkerDragStart(Marker marker) {\n                chosen[0] = marker.getPosition();\n            }\n        });\n        picker.getOverlays().add(selected);\n\n        // Se a foto terminar de carregar com a tela aberta, troca as iniciais pela foto sem refazer o mapa.\n        if (!forOrigin) {\n            PassengerAvatar.preload(this, token, () -> {\n                if (!destroyed && selected.getPosition() != null) {\n                    selected.setIcon(PassengerAvatar.markerDrawable(this));\n                    picker.invalidate();\n                }\n            });\n        }\n\n        MapEventsOverlay events = new MapEventsOverlay(new MapEventsReceiver() {\n            @Override public boolean singleTapConfirmedHelper(GeoPoint point) {\n                chosen[0] = point;\n                selected.setPosition(point);\n                selected.setTitle(forOrigin ? "Embarque escolhido" : "Destino escolhido");\n                if (!forOrigin && fixedOrigin != null) {\n                    previewLine.setPoints(Arrays.asList(fixedOrigin, point));\n                }\n                picker.invalidate();\n                return true;\n            }\n            @Override public boolean longPressHelper(GeoPoint point) {\n                return singleTapConfirmedHelper(point);\n            }\n        });\n        picker.getOverlays().add(0, events);\n        TextView tip = text(forOrigin\n                ? "Toque no mapa ou arraste o marcador para ajustar o embarque."\n                : "Arraste sua FOTO da origem até o destino. Você também pode tocar no ponto desejado.",\n                13, Color.WHITE, true);\n'''

if old_block not in text:
    raise SystemExit('Bloco do marcador móvel v1.2 não encontrado')
text = text.replace(old_block, new_block, 1)

# Botão deixa explícito o que está sendo confirmado.
old_confirm = '''        Button back = secondaryLight("Voltar"); Button confirm = primary("Confirmar local");\n'''
new_confirm = '''        Button back = secondaryLight("Voltar"); Button confirm = primary(forOrigin ? "Confirmar embarque" : "Confirmar destino");\n'''
if old_confirm not in text:
    raise SystemExit('Botão de confirmação não encontrado')
text = text.replace(old_confirm, new_confirm, 1)

# Mantemos a rota real somente após a confirmação. Nenhuma chamada de rota ocorre durante o arraste.
build_path = Path('app/build.gradle')
build = build_path.read_text(encoding='utf-8')
build = build.replace('versionCode 12', 'versionCode 14', 1)
build = build.replace("versionName '1.2-native-beta'", "versionName '1.4-native-beta'", 1)
build_path.write_text(build, encoding='utf-8')

path.write_text(text, encoding='utf-8')
print('Passageiro v1.4: foto arrastável da origem ao destino, sem rota durante o gesto.')
